// ===============================================================================
// DAEMIND SRE - GUARDRAIL DE SEGURANÇA SQL (READ-ONLY)
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = { query_sql: "SELECT COUNT(*) AS total_pedidos FROM pedidos WHERE status_operacional = 'Pago';" };
}

let sql = (parsed.query_sql || '').trim();
const upper = sql.toUpperCase();

// Bloqueio de injeção ou comandos destrutivos
if (!upper.startsWith('SELECT') || upper.includes('DROP') || upper.includes('DELETE') || upper.includes('UPDATE') || upper.includes('TRUNCATE') || upper.includes('ALTER')) {
  sql = "SELECT 'Consulta bloqueada por política de segurança SRE.' AS aviso;";
}

return [{
  json: {
    query_sql_safe: sql,
    sender_whatsapp: $('Sanitizar Pergunta').item.json.sender_whatsapp,
    pergunta_original: $('Sanitizar Pergunta').item.json.pergunta_usuario
  }
}];

